/* ---- GRAFICA DI PROVA: forzieri, bauli e falò con fiamma viva ---- */
GfxNew.chest=function(){
  const D={"ferro_c": "", "ferro_a": "", "oro_c": "", "oro_a": "", "falo_b": "", "falo_f": ""},M={"ferro_c": [60.0, 44.1, 30.0, 43.2], "ferro_a": [65.3, 68.4, 30.8, 66.8], "oro_c": [60.0, 47.8, 30.0, 46.9], "oro_a": [65.5, 63.1, 35.3, 60.3], "falo_b": [84.0, 73.9, 42.0, 62.8], "falo_f": [48.4, 53.1, 22.5, 62.9]};
  const mkA=(k,sink,shk,cb)=>{const m=M[k],lw=m[0],lh=m[1],img=new Image(),[c,x]=mk(lw,lh),s={c,w:lw,h:lh,ax:m[2],ay:m[3],art:1,sink:sink,shk:shk||1};
    img.onload=()=>{x.clearRect(0,0,lw,lh);x.drawImage(img,0,0,lw,lh);
      const ao=x.createLinearGradient(0,lh*.82,0,lh);ao.addColorStop(0,'rgba(30,18,6,0)');ao.addColorStop(1,'rgba(30,18,6,.34)');x.globalCompositeOperation='source-atop';x.fillStyle=ao;x.fillRect(0,0,lw,lh);x.globalCompositeOperation='source-over';
      const[c2,x2]=mk(lw,lh);x2.drawImage(c,0,0,lw,lh);x2.globalCompositeOperation='source-in';x2.fillStyle='#0e1c0a';x2.fillRect(0,0,lw,lh);s.sh=c2;s.ok=1;if(cb)cb(s)};
    img.src='data:image/webp;base64,'+D[k];return s};
  const fc=mkA('ferro_c',-3,.55),fa=mkA('ferro_a',-3,.55),oc=mkA('oro_c',-3,.55),oa=mkA('oro_a',-3,.55);
  SP.chest=[[fc,fa],[fc,fa],[fc,fa],[oc,oa]];
  /* falò: base (pietre e ciocchi) + fiamma dipinta separata, che si anima */
  const fb=mkA('falo_b',4,.35),ff=mkA('falo_f',0,1,GfxNew.flameFrames);fb.fl=ff;
  fb.ay=M.falo_b[3];SP.falo=fb;
};
/* fiamma: fotogrammi pre-deformati (nessuna cucitura), mescolati in continuo + guizzo, scoppi di faville e luce che pulsa */
GfxNew.flameFrames=function(f){
  const N=16,PAD=8,cw=f.c.width,ch=f.c.height,ow=cw+PAD*2,x0=f.c.getContext('2d'),src=x0.getImageData(0,0,cw,ch).data;
  const mkSet=(a1,a2,a3,k1,k2,ph0)=>{const arr=[];
    for(let n=0;n<N;n++){const ph=n/N,c=document.createElement('canvas');c.width=ow;c.height=ch;const x=c.getContext('2d'),im=x.createImageData(ow,ch),d=im.data;
      for(let y=0;y<ch;y++){const u=1-(y+.5)/ch,yy=y/ch,T=Math.PI*2;
        const dx=(Math.sin(T*(ph*2+yy*k1+ph0))*a1+Math.sin(T*(ph*3+yy*k2+.3+ph0))*a2+Math.sin(T*(ph+.2+ph0))*a3*u)*Math.pow(u,1.25)*SS;
        for(let X=0;X<ow;X++){const sx=X-PAD-dx,i0=Math.floor(sx),w=sx-i0;let a=0,r=0,gg=0,b=0;
          for(let q=0;q<2;q++){const xi=i0+q;if(xi<0||xi>=cw)continue;const wt=q?w:1-w,o=(y*cw+xi)*4,al=src[o+3]/255*wt;a+=al;r+=src[o]*al;gg+=src[o+1]*al;b+=src[o+2]*al}
          const o2=(y*ow+X)*4;if(a>.003){d[o2]=r/a;d[o2+1]=gg/a;d[o2+2]=b/a;d[o2+3]=a*255}}}
      x.putImageData(im,0,0);arr.push(c)}
    return arr};
  f.fA=mkSet(1.05,.55,1.3,3.2,5.5,0);f.fB=mkSet(.8,.7,1.0,4.6,7.3,.37);f.pad=PAD;f.N=N;f.fw=ow/SS;f.fh=ch/SS;f.fr=1;
};
GfxNew.faloDraw=function(g,t,k){
  const s=SP.falo,f=s&&s.fl;k=k||1;
  if(!f||!f.ok||!s.ok||!f.fr){if(s&&s.ok){artGround(g,s,1,s.w*.4);drawSp(g,s,0,0,1)}return}
  const hs=(n)=>{const v=Math.sin(n*127.1+311.7)*43758.5453;return v-Math.floor(v)};
  const big=(typeof FE!=='undefined'&&FE.on&&FE.on())?1.18:1;
  const ev=Math.floor(t*1.15),ef=t*1.15-ev,popOn=hs(ev)>.35?Math.max(0,1-ef*3.2):0,pop=popOn*popOn;   // scoppio: breve vampata
  const pl=.82+.12*Math.sin(t*7.3)+.06*Math.sin(t*13.1+1.3)+pop*.25;
  artGround(g,s,1,s.w*.4);
  // chiarore sul terreno
  g.save();g.globalCompositeOperation='lighter';
  const gg=g.createRadialGradient(0,-4,3,0,-4,60);gg.addColorStop(0,'rgba(255,150,50,'+(.22*pl)+')');gg.addColorStop(.55,'rgba(255,100,30,'+(.07*pl)+')');gg.addColorStop(1,'rgba(255,80,20,0)');
  g.fillStyle=gg;g.beginPath();g.ellipse(0,-2,62,32,0,0,7);g.fill();g.restore();
  // fiamma dietro i ciocchi
  const sy=(1+.05*Math.sin(t*9.1)+.035*Math.sin(t*15.3+1.1)+pop*.14)*big,sx=1-(sy-1)*.45;
  const cxL=-f.ax+f.w/2,bot=-f.ay+f.h,W=f.fw*sx,H=f.fh*sy;
  const lay=(arr,T,al,sc)=>{const q=((t/T)%1+1)%1*f.N,i0=Math.floor(q)%f.N,i1=(i0+1)%f.N,fr=q-Math.floor(q),w=W*sc,h=H*sc;
    g.globalAlpha=al;g.drawImage(arr[i0],cxL-w/2,bot-h,w,h);g.globalAlpha=al*fr;g.drawImage(arr[i1],cxL-w/2,bot-h,w,h);g.globalAlpha=1};
  lay(f.fA,1.25,1,1);
  g.save();g.globalCompositeOperation='lighter';lay(f.fB,.8,.2+pop*.25,1.05);g.restore();
  drawSp(g,s,0,0,1);
  // bagliore sulla legna
  g.save();g.globalCompositeOperation='lighter';
  const bg=g.createRadialGradient(0,-8,2,0,-8,30);bg.addColorStop(0,'rgba(255,170,70,'+(.34*pl)+')');bg.addColorStop(1,'rgba(255,90,20,0)');
  g.fillStyle=bg;g.beginPath();g.ellipse(0,-6,30,13,0,0,7);g.fill();
  // scintille che salgono
  const NS=big>1?20:10;
  for(let i=0;i<NS;i++){const p=(t*.42+i*.137)%1,x=Math.sin(i*5.1+t*1.6)*13*p+(i%5-2)*2.4,y=-18-p*54;
    g.fillStyle='rgba(255,'+(170+((i*29)%60))+',90,'+(.9*(1-p))+')';g.beginPath();g.arc(x,y,.5+(1-p)*1.1,0,7);g.fill()}
  // scoppio: raffica di faville che schizzano fuori
  if(popOn>0){const n=7+Math.floor(hs(ev+9)*5),tt=ef*.9;
    for(let i=0;i<n;i++){const a=-Math.PI/2+(hs(ev*13+i)-.5)*2.5,v=18+hs(ev*7+i*3)*34,x=Math.cos(a)*v*tt+(hs(ev+i)-.5)*6,y=-22+Math.sin(a)*v*tt+90*tt*tt;
      g.fillStyle='rgba(255,'+(200+((i*17)%50))+',120,'+(Math.max(0,1-ef*2.6))+')';g.beginPath();g.arc(x,y,.9+hs(i+ev)*.9,0,7);g.fill()}}
  g.restore();
};
